set -euo pipefail; python3 - <<'PY'
from pathlib import Path

def replace_once(path, old, new):
    p = Path(path)
    s = p.read_text()
    if s.count(old) != 1:
        raise SystemExit(f'{path}: expected one match for {old!r}, found {s.count(old)}')
    p.write_text(s.replace(old, new, 1))

replace_once('interface/vite.config.ts', "import { createLogger, defineConfig, type Logger, type UserConfig } from 'vite';", "import { createLogger, type Logger, type UserConfig } from 'vite';\nimport { defineConfig } from 'vitest/config';")
replace_once('interface/vite.config.ts', "\t\tbuild: {\n", "\t\ttest: {\n\t\t\tsetupFiles: ['./src/test/setup.ts']\n\t\t},\n\t\tbuild: {\n")

p = Path('interface/src/test/setup.ts')
p.parent.mkdir(parents=True, exist_ok=True)
p.write_text("""function exposeWindowStorage(name: 'localStorage' | 'sessionStorage') {
\tif (typeof window === 'undefined') return;
\tconst storage = name === 'localStorage' ? window.localStorage : window.sessionStorage;
\tObject.defineProperty(globalThis, name, {
\t\tconfigurable: true,
\t\tenumerable: true,
\t\tvalue: storage,
\t\twritable: true
\t});
}

exposeWindowStorage('localStorage');
exposeWindowStorage('sessionStorage');
""")

replace_once('interface/src/lib/storage.svelte.ts', 'const stored = localStorage.getItem(key);', 'const stored = window.localStorage.getItem(key);')
replace_once('interface/src/lib/storage.svelte.ts', 'localStorage.setItem(key, v);', 'window.localStorage.setItem(key, v);')

